CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id,email,full_name) VALUES(NEW.id,coalesce(NEW.email,''),coalesce(NEW.raw_user_meta_data->>'full_name',NEW.raw_user_meta_data->>'name','')) ON CONFLICT(id) DO NOTHING; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.handle_new_user() FROM PUBLIC, anon, authenticated;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname='on_auth_user_created' AND tgrelid='auth.users'::regclass) THEN CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user(); END IF; END $$;
CREATE OR REPLACE FUNCTION public.ensure_customer_profile() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in to continue'; END IF; INSERT INTO public.profiles(id,email,full_name) SELECT id,coalesce(email,''),coalesce(raw_user_meta_data->>'full_name',raw_user_meta_data->>'name','') FROM auth.users WHERE id=auth.uid() ON CONFLICT(id) DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.ensure_customer_profile() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.ensure_customer_profile() TO authenticated;
INSERT INTO public.profiles(id,email,full_name) SELECT id,coalesce(email,''),coalesce(raw_user_meta_data->>'full_name',raw_user_meta_data->>'name','') FROM auth.users ON CONFLICT(id) DO NOTHING;